// sb-core-tests.cpp — Portable DSP regressions, table integrity and performance measurements.
#include "sb-engine.h"
#include <iostream>
#include <iomanip>
#include <chrono>
#include <cstdlib>
using namespace SynthB;
static void demand(bool result,const char* name){if(!result){std::cerr<<"FAIL: "<<name<<'\n';std::exit(1);}}
static void put(State& s,const std::string& key,float value){int index=Schema::get().find(key);demand(index>=0,key.c_str());s[size_t(index)]=value;}
static double run(Instrument& synth,int blocks,int keys=0,const WaveSet* imported=nullptr){std::array<float,256> l{},r{};std::array<Event,32> events{};for(int i=0;i<keys;++i)events[size_t(i)]={Event::Down,0,48+i,1,.8f};double energy=0;for(int block=0;block<blocks;++block){synth.render(l.data(),r.data(),256,events.data(),block==0?keys:0,0,-1,imported);for(int n=0;n<256;++n){demand(std::isfinite(l[size_t(n)])&&std::isfinite(r[size_t(n)]),"finite stereo");demand(std::abs(l[size_t(n)])<.65f&&std::abs(r[size_t(n)])<.65f,"output ceiling");energy+=l[size_t(n)]*l[size_t(n)]+r[size_t(n)]*r[size_t(n)];}}return energy;}
int main(int argc,char** argv){
 const auto& schema=Schema::get();if(argc>1&&std::string(argv[1])=="--schema"){std::cout<<"[\n";for(size_t i=0;i<schema.specs.size();++i){if(i)std::cout<<",\n";auto& p=schema.specs[i];std::cout<<"{\"key\":"<<std::quoted(p.key)<<",\"title\":"<<std::quoted(p.title)<<",\"section\":"<<std::quoted(p.section)<<",\"min\":"<<p.low<<",\"max\":"<<p.high<<",\"default\":"<<p.initial<<",\"integer\":"<<(p.integer?"true":"false")<<",\"choices\":[";for(size_t j=0;j<p.options.size();++j){if(j)std::cout<<",";std::cout<<std::quoted(p.options[j]);}std::cout<<"]}";}std::cout<<"\n]\n";return 0;}
 for(size_t i=0;i<schema.specs.size();++i)demand(schema.find(schema.specs[i].key)==int(i),"unique schema IDs");
 auto start=std::chrono::steady_clock::now();const auto& tables=Tables::get();double tableTime=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();
 for(auto& table:tables.library){demand(table->frames==64,"64 frames");for(auto& level:table->layers){demand(level.samples.size()==size_t(level.length*64),"complete mip storage");for(float x:level.samples)demand(std::isfinite(x)&&std::abs(x)<1.6f,"bounded table content");}float difference=0;for(int n=0;n<256;++n)difference+=std::abs(table->visual(float(n)/256,0)-table->visual(float(n)/256,.371f));demand(difference>1,"table morph is audible");}
 Instrument engine;engine.prepare(48000);demand(run(engine,8)==0,"silent initialization");demand(run(engine,30,1)>1.e-6,"notes generate signal");engine.message({Event::Up,0,48,1,0});run(engine,350);demand(engine.active()==0,"note-off releases");
 engine.reset();run(engine,2,24);demand(engine.active()==16,"bounded voice allocation");engine.reset();demand(run(engine,8)==0,"panic clears histories");
 engine.message({Event::Controller,0,64,1,127});run(engine,2,1);engine.message({Event::Up,0,48,1,0});run(engine,150);demand(engine.active()==1,"sustain holds");engine.message({Event::Controller,0,64,1,0});run(engine,350);demand(engine.active()==0,"sustain releases");
 State state=schema.initial();put(state,"voice.mode",2);engine.parameters(state);engine.reset();engine.message({Event::Down,0,60,1,.8f});engine.message({Event::Down,0,64,1,.8f});engine.message({Event::Up,0,64,1,0});run(engine,20);demand(engine.active()==1,"legato last-note return");engine.message({Event::Up,0,60,1,0});run(engine,350);demand(engine.active()==0,"legato releases");
 for(int type=0;type<9;++type)for(int route=0;route<4;++route){state=schema.initial();put(state,"flt1.type",float(type));put(state,"flt1.res",1);put(state,"flt1.drive",1);put(state,"flt1.cutoff",80);put(state,"flt2.on",1);put(state,"filter.route",float(route));engine.parameters(state);engine.reset();run(engine,15,8);}
 for(int warp=0;warp<12;++warp){state=schema.initial();put(state,"osc1.warp1.type",float(warp));put(state,"osc1.warp1.amount",1);put(state,"osc2.warp2.type",float(11-warp));put(state,"osc2.warp2.amount",1);engine.parameters(state);engine.reset();run(engine,20,8);}
 for(int lane=0;lane<2;++lane){state=schema.initial();put(state,lane==0?"arp.on":"seq.on",1);engine.parameters(state);engine.reset();demand(run(engine,80,4)>1.e-5,"sequence emits notes");for(int n=0;n<4;++n)engine.message({Event::Up,0,48+n,1,0});run(engine,400);demand(engine.active()==0,"sequencer releases all notes");}
 // Table import and exact pitch test use a pure single cycle, with effects/macros disabled.
 std::vector<float> sine(2048);for(int n=0;n<2048;++n)sine[size_t(n)]=std::sin(float(tau*n/2048));auto imported=WaveSet::fromFrames(sine,1,"Test sine");
 state=schema.initial();put(state,"osc1.table",30);put(state,"osc1.uni.voices",1);put(state,"osc2.level",0);put(state,"mix.sub",0);put(state,"flt1.on",0);put(state,"macro.euphoria",0);put(state,"macro.space",0);put(state,"env1.sustain",1);for(int f=1;f<=10;++f)put(state,"fx"+std::to_string(f)+".on",0);engine.parameters(state);engine.reset();engine.message({Event::Down,0,69,1,1});run(engine,20,0,imported.get());std::array<float,48000> l{},r{};engine.render(l.data(),r.data(),48000,nullptr,0,0,-1,imported.get());int crossings=0;for(int n=1;n<48000;++n)if(l[size_t(n-1)]<=0&&l[size_t(n)]>0)++crossings;demand(std::abs(crossings-440)<=1,"imported sine A4 pitch");
 state=schema.initial();put(state,"mod1.source",4);put(state,"mod1.depth",1);for(size_t i=0;i<schema.specs.size();++i){put(state,"mod1.destination",float(i+1));engine.parameters(state);engine.reset();run(engine,2,1);}
 std::cout<<"PASS: "<<schema.specs.size()<<" parameters; 30 x 64-frame tables; 10 mip levels; MIDI, sustain, legato, stealing, 9 filters, 12 warp selections, arp/seq, WAV-table pitch, all modulation destinations.\n";
 std::cout<<"Wavetable generation: "<<tableTime<<" seconds, once per process.\n";
 for(int voices:{1,4,8,16}){state=schema.initial();put(state,"osc1.uni.voices",float(voices));put(state,"osc2.uni.voices",float(voices));put(state,"osc2.level",.6f);engine.parameters(state);engine.reset();auto t=std::chrono::steady_clock::now();run(engine,188,16);double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count();std::cout<<"16 notes x 2 oscillators x "<<voices<<" unison, 48k/256: "<<seconds<<" s for 1.003 s audio, "<<seconds/1.003*100<<"% of a core offline.\n";}
}
